const on  = 'ON';
this.changePaintOpacity(!value);
this.drawText(off, rect.x + halfWidth, rect.y, quarterWidth, "center");
this.changePaintOpacity(value);
this.drawText(on, rect.x + halfWidth + quarterWidth, rect.y, quarterWidth, "center");"

