const index = arguments[1];
const title = this.commandName(index);
const rect = this.itemLineRect(index);
const halfWidth = rect.width / 2;
const value = this.getConfigValue(symbol);

// Draw Command Name
this.resetFontSettings();
this.changePaintOpacity(true);
this.drawTextEx(title, rect.x, rect.y, halfWidth, "left");

// Draw Gauge
const rate = (value / 10).clamp(0, 1);
const gx = rect.x + halfWidth;
const gy = rect.y + rect.height - 14;
const fillW = Math.floor((halfWidth - 2) * rate);
const color0 = ColorManager.gaugeBackColor();
const color1 = ColorManager.textColor(30);
const color2 = ColorManager.textColor(31);
this.contents.fillRect(gx, gy, halfWidth, 12, color0);
this.contents.gradientFillRect(gx + 1, gy + 1, fillW, 10, color1, color2);

// Draw Value
const text = 'x%1'.format(2 ** value);
this.drawText(text, rect.x + halfWidth, rect.y, halfWidth, "center");

default.ProcessOkJS:
// Declare Constants
const symbol = arguments[0];
let value = this.getConfigValue(symbol);
const lastValue = value;

// Perform Actions
if (value >= 10 && (Input.isTriggered("ok") || TouchInput.isClicked())) {
    value = 0;
} else {
    value += 1;
    value = value.clamp(0, 10);
}
this.setConfigValue(symbol, value);
this.redrawItem(this.findSymbol(symbol));
if (lastValue !== value) {
    this.playCursorSound();
}

